#include <stdio.h>

int main() {
    int sum = 0, i = 1;
    // do-while 先执行循环体，i 自增后才检查是否还要继续。
    do {
        sum += i;
        i++;
    } while (i <= 100);
    printf("%d\n", sum);
    return 0;
}
